pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 initialSupply, address target, uint256 mintedAmount, uint256 burnValue) public {
        // Restrict inputs to avoid overflow
        vm.assume(initialSupply < type(uint256).max / 10);
        vm.assume(mintedAmount < type(uint256).max / 10);
        vm.assume(burnValue < type(uint256).max / 10);

        // Deploy with initialSupply
        c = new C(initialSupply, "", "");

        // Mint tokens to target
        c.mintToken(target, mintedAmount);

        // Burn some tokens (only owner can burn)
        c.burn(burnValue);

        // After burn, totalSupply should be <= initialSupply*10^0 + mintedAmount (the correct invariant)
        // For reference: totalSupply = initialSupply + mintedAmount - burnValue (if burn succeeds)
        // The bug adds 1 extra to totalSupply during mint, so after burn totalSupply becomes initialSupply + mintedAmount + 1 - burnValue
        // So assert that totalSupply <= initialSupply + mintedAmount (since burn can't exceed balance)
        uint256 expectedMaxTotalSupply = initialSupply + mintedAmount;
        assertTrue(c.totalSupply() <= expectedMaxTotalSupply, "totalSupply exceeded expected maximum after burn");
    }
}

