pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 initialSupply, uint256 mintAmount, uint256 burnAmount) public {
        // Mint some tokens first so the owner has balance to burn
        initialSupply = bound(initialSupply, 0, 1e30);
        mintAmount = bound(mintAmount, 0, 1e30);
        burnAmount = bound(burnAmount, 0, 1e30);
        // But ensure totalSupply + mintAmount does not overflow
        vm.assume(initialSupply + mintAmount < type(uint256).max);

        // Deploy with initial supply (Note: setUp already did, but we need a fresh contract with the given initialSupply)
        c = new C(initialSupply, "Test", "TST");
        // Mint tokens
        c.mintToken(address(this), mintAmount);
        // Record totalSupply before burn
        uint256 before = c.totalSupply();
        // Burn some amount, but not more than balanceOf[owner]
        // The owner is address(this) after deployment
        uint256 ownerBalance = c.balanceOf(address(this));
        // We need to call burn, but it reverts if _value > balanceOf[msg.sender]
        // So we restrict burnAmount to <= ownerBalance
        vm.assume(burnAmount <= ownerBalance);
        c.burn(burnAmount);
        uint256 after = c.totalSupply();
        // Rule: totalSupply decreases by exactly burnAmount
        assertTrue(after == before - burnAmount);
    }
}

