pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(address caller, uint256 burnAmount) public {
        vm.assume(burnAmount <= type(uint256).max / 2);
        // Mint some tokens to caller first
        uint256 mintAmount = bound(uint256(keccak256(abi.encode(caller, burnAmount))), 1, type(uint256).max / 2);
        c.mintToken(caller, mintAmount);
        // Record state before burn
        uint256 balanceBefore = c.balanceOf(caller);
        uint256 supplyBefore = c.totalSupply();
        // Attempt burn
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.burn.selector, burnAmount));
        if (success) {
            uint256 balanceAfter = c.balanceOf(caller);
            uint256 supplyAfter = c.totalSupply();
            assertTrue(
                (supplyBefore - supplyAfter) == (balanceBefore - balanceAfter),
                "Decrease in totalSupply should equal decrease in caller's balance"
            );
        } else {
            // If burn reverted, totalSupply and balance must be unchanged
            assertTrue(
                c.totalSupply() == supplyBefore && c.balanceOf(caller) == balanceBefore,
                "If burn fails, state must be unchanged"
            );
        }
    }
}

