pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 burnAmount) public {
        vm.assume(burnAmount > 0);
        // Ensure owner can burn
        vm.assume(c.balanceOf(address(this)) >= burnAmount);
        // Record state before burn
        uint256 balanceBefore = c.balanceOf(address(this));
        uint256 supplyBefore = c.totalSupply();
        // Perform burn
        (bool success, ) = address(c).call(abi.encodeWithSignature("burn(uint256)", burnAmount));
        // If it reverts, still check invariant: if success, then balance decreases by burnAmount
        if (success) {
            uint256 balanceAfter = c.balanceOf(address(this));
            uint256 supplyAfter = c.totalSupply();
            // The general rule: balanceOf[caller] decreases by exactly burnAmount, and totalSupply decreases by burnAmount
            assertTrue(balanceAfter == balanceBefore - burnAmount && supplyAfter == supplyBefore - burnAmount);
        } else {
            // If it reverted, state must be unchanged
            uint256 balanceAfter = c.balanceOf(address(this));
            uint256 supplyAfter = c.totalSupply();
            assertTrue(balanceAfter == balanceBefore && supplyAfter == supplyBefore);
        }
    }
}

