// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 burnAmount) public {
        vm.assume(burnAmount > 0 && burnAmount <= c.balanceOf(address(this)));

        c.burn(burnAmount);

        // After burn, sum of all balances should equal totalSupply
        // We can't enumerate all addresses, but we can check that the caller's balance plus
        // totalSupply minus caller's balance (which covers the rest) is consistent
        // Actually, the invariant we need: totalSupply == sum of all balanceOf
        // Since we can't sum all, we check a necessary condition: totalSupply >= 0 and
        // balanceOf(caller) <= totalSupply, but that's weak. Instead, we check that
        // totalSupply + burnAmount == previous totalSupply (if no minting happened), but that's just testing the implementation.
        // The strongest checkable property is that totalSupply is non-negative and balanceOf(caller) <= totalSupply.
        // But the bug makes balanceOf increase, so totalSupply won't match. Let's check a stronger invariant:
        // The sum of balanceOf[owner] and balanceOf[caller] is <= totalSupply? No.
        // Let's use a simpler check: totalSupply should be equal to balanceOf(c.owner()) + (sum of others) but we can't.
        // We need a property that holds in reference and breaks in mutant. The mutant increases balanceOf[caller] while decreasing totalSupply.
        // So after burn: in reference, totalSupply decreases and balanceOf[caller] decreases (same amount).
        // In mutant, totalSupply decreases but balanceOf[caller] increases (wrong direction).
        // So after a burn, the invariant "totalSupply == old totalSupply - burnAmount" holds for both.
        // But the difference is in balanceOf[caller]. Let's check a property that relates them:
        // In reference: balanceOf[caller] + totalSupply == old balanceOf[caller] + old totalSupply - 2*burnAmount
        // That changes. The best property: after burn, the change in balanceOf[caller] should equal the negative of the change in totalSupply.
        uint balanceBefore = c.balanceOf(address(this));
        uint supplyBefore = c.totalSupply();
        c.burn(burnAmount);
        uint balanceAfter = c.balanceOf(address(this));
        uint supplyAfter = c.totalSupply();
        // In reference: balanceAfter = balanceBefore - burnAmount, supplyAfter = supplyBefore - burnAmount
        // So (balanceBefore - balanceAfter) == burnAmount and (supplyBefore - supplyAfter) == burnAmount
        // In mutant: balanceAfter = balanceBefore + burnAmount, supplyAfter = supplyBefore - burnAmount
        // So (balanceBefore - balanceAfter) == -burnAmount, not equal to (supplyBefore - supplyAfter) == burnAmount
        assertTrue(balanceBefore - balanceAfter == supplyBefore - supplyAfter, "!");
    }
}

